dcm2niix_path = "/home/liushiyu/liutuo-test/dcm2niix_lnx/dcm2niix"  # 明确指定 dcm2niix 的路径

# 检查 dcm2niix 是否可用
def check_tools():
    if not os.path.isfile(dcm2niix_path):
        print(f"Error: dcm2niix not found at {dcm2niix_path}. Please check the path.")
        exit(1)
    try:
        subprocess.run([dcm2niix_path, "-h"], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        print("dcm2niix is ready to use.")
    except Exception as e:
        print(f"Error: Unable to run dcm2niix. Details: {e}")
        exit(1)

# 遍历目录并处理文件
def process_directory(directory):
    for root, dirs, files in os.walk(directory):
        # 限制目录深度为5级
        if root[len(directory):].count(os.sep) > 5:
            continue

        nii_files = [f for f in files if f.endswith(".nii")]
        dcm_files = [f for f in files if f.endswith(".dcm")]

        if nii_files:
            print(f"Processing NII files in: {root}")
            for nii_file in nii_files:
                nii_path = os.path.join(root, nii_file)
                gzip_nii(nii_path)

        if dcm_files:
            print(f"Processing DCM files in: {root}")
            convert_dcm_to_nii_gz(root, dcm_files)

# 将 .nii 文件压缩为 .nii.gz
def gzip_nii(nii_path):
    output_path = nii_path + ".gz"
    try:
        with open(nii_path, "rb") as f_in:
            with open(output_path, "wb") as f_out:
                subprocess.run(["gzip"], stdin=f_in, stdout=f_out, check=True)
        print(f"Compressed: {nii_path} -> {output_path}")
    except Exception as e:
        print(f"Error compressing {nii_path}: {e}")

# 将 .dcm 文件转换为 .nii.gz
def convert_dcm_to_nii_gz(directory, dcm_files):
    try:
        # 使用 dcm2niix 将 .dcm 转换为 .nii
        subprocess.run(
            [dcm2niix_path, "-o", directory, "-f", "converted", directory],
            check=True
        )
        print(f"Converted DICOM files in {directory} to NIfTI format.")
    except subprocess.CalledProcessError as e:
        print(f"Error during dcm2niix conversion in {directory}: {e}")
        return

    # 找到生成的 .nii 文件并压缩
    for file in os.listdir(directory):
        if file.endswith(".nii"):
            nii_path = os.path.join(directory, file)
            gzip_nii(nii_path)

# 主函数
if __name__ == "__main__":
    check_tools()
    process_directory(root_dir)

import os
import subprocess

# 定义根目录和 dcm2niix 路径
root_dir = "/home/liushiyu/liutuo-test/two trace pet/New Folder"
dcm2niix_path = "/home/liushiyu/liutuo-test/dcm2niix_lnx/dcm2niix"  # 明确指定 dcm2niix 的路径

# 检查 dcm2niix 是否可用
def check_tools():
    if not os.path.isfile(dcm2niix_path):
        print(f"Error: dcm2niix not found at {dcm2niix_path}. Please check the path.")
        exit(1)
    try:
        subprocess.run([dcm2niix_path, "-h"], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        print("dcm2niix is ready to use.")
    except Exception as e:
        print(f"Error: Unable to run dcm2niix. Details: {e}")
        exit(1)

# 遍历目录并处理文件
def process_directory(directory):
    for root, dirs, files in os.walk(directory):
        # 限制目录深度为5级
        if root[len(directory):].count(os.sep) > 5:
            continue

        nii_files = [f for f in files if f.endswith(".nii")]
        dcm_files = [f for f in files if f.endswith(".dcm")]

        if nii_files:
            print(f"Processing NII files in: {root}")
            for nii_file in nii_files:
                nii_path = os.path.join(root, nii_file)
                gzip_nii(nii_path)

        if dcm_files:
            print(f"Processing DCM files in: {root}")
            convert_dcm_to_nii_gz(root)

# 将 .nii 文件压缩为 .nii.gz
def gzip_nii(nii_path):
    output_path = nii_path + ".gz"
    try:
        with open(nii_path, "rb") as f_in:
            with open(output_path, "wb") as f_out:
                subprocess.run(["gzip"], stdin=f_in, stdout=f_out, check=True)
        print(f"Compressed: {nii_path} -> {output_path}")
        # 删除原始 .nii 文件
        os.remove(nii_path)
        print(f"Removed original file: {nii_path}")
    except Exception as e:
        print(f"Error compressing {nii_path}: {e}")

# 将 .dcm 文件直接转换为 .nii.gz
def convert_dcm_to_nii_gz(directory):
    try:
        # 使用 dcm2niix 直接生成 .nii.gz 文件
        subprocess.run(
            [dcm2niix_path, "-o", directory, "-f", "converted", "-z", "y", directory],
            check=True
        )
